import json
import sys


def first_binary_index(values, target):
    left = 0
    right = len(values)
    while left < right:
        middle = (left + right) // 2
        if values[middle] < target:
            left = middle + 1
        else:
            right = middle
    if left < len(values) and values[left] == target:
        return left
    return -1


data = json.load(sys.stdin)
print(first_binary_index(data["values"], data["target"]))

