function firstBinaryIndex(values, target) {
  let left = 0;
  let right = values.length;
  while (left < right) {
    const middle = Math.floor((left + right) / 2);
    if (values[middle] < target) {
      left = middle + 1;
    } else {
      right = middle;
    }
  }
  if (left < values.length && values[left] === target) {
    return left;
  }
  return -1;
}

