def balanced(text):
    pending = []
    closers = {"(": ")", "[": "]"}
    for token in text:
        if token in closers:
            pending.append(closers[token])
        elif len(pending) == 0 or pending.pop() != token:
            return False
    return len(pending) == 0


for text in ["([[]])", "([)]", "(", ")", ""]:
    print(int(balanced(text)))

function balanced(text) {
  const pending = [];
  for (const token of text) {
    if (token === "(") {
      pending.push(")");
    } else if (token === "[") {
      pending.push("]");
    } else if (pending.length === 0 || pending.pop() !== token) {
      return false;
    }
  }
  return pending.length === 0;
}

for (const text of ["([[]])", "([)]", "(", ")", ""]) {
  console.log(balanced(text) ? 1 : 0);
}

from collections import deque
import json


def served_ids(events):
    pending = deque()
    result = []
    for event in events:
        if event != "serve":
            pending.append(event)
        elif len(pending) > 0:
            result.append(pending.popleft())
        else:
            result.append(-1)
    return result


print(json.dumps(served_ids([4, 9, "serve", 4, "serve", "serve", "serve"]),
                 separators=(",", ":")))
print(json.dumps(served_ids([])))

function servedIds(events) {
  const pending = [];
  const result = [];
  let head = 0;
  for (const event of events) {
    if (event !== "serve") {
      pending.push(event);
    } else if (head < pending.length) {
      result.push(pending[head]);
      head += 1;
    } else {
      result.push(-1);
    }
  }
  return result;
}

console.log(JSON.stringify(servedIds([4, 9, "serve", 4, "serve", "serve", "serve"])));
console.log(JSON.stringify(servedIds([])));

def sum_from(values, index=0):
    if index == len(values):
        return 0
    return values[index] + sum_from(values, index + 1)


print(sum_from([3, 3, -2]))
print(sum_from([]))
print(sum_from([5, -3, 8], 1))

function sumFrom(values, index = 0) {
  if (index === values.length) {
    return 0;
  }
  return values[index] + sumFrom(values, index + 1);
}

console.log(sumFrom([3, 3, -2]));
console.log(sumFrom([]));
console.log(sumFrom([5, -3, 8], 1));

